import{_ as t,o,c as a,a2 as s}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"How It Works","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/how-it-works.md","filePath":"en/guide/how-it-works.md","lastUpdated":1785861127000}'),n={name:"en/guide/how-it-works.md"};function i(r,e,l,h,d,c){return o(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h1><p>This page describes how CZero operates day to day, so you have something concrete to go on when judging whether a task ran as expected.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>CZero has no resident Java service. Responsibilities are split into three stages: <strong>install time</strong> prepares the configuration, <strong>boot time</strong> starts one extremely lightweight scheduling process, and from then on that process triggers each task in the background according to the config.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Install  ──►  Boot  ──►  Runtime</span></span>
<span class="line"><span>language / inherit   start scheduler   trigger cleaning per config.json</span></span></code></pre></div><p>The scheduler is the only resident process, and it sleeps almost all of the time, waking only to dispatch a task. The cleaners themselves exit when done and consume no background resources.</p><h2 id="at-install-time" tabindex="-1">At install time <a class="header-anchor" href="#at-install-time" aria-label="Permalink to &quot;At install time&quot;">​</a></h2><p>Flashing asks you two things via the volume keys:</p><ol><li><strong>Choose a language</strong> — Volume Up = English, Volume Down = 中文; defaults to Chinese after roughly 60 seconds without input.</li><li><strong>Inherit the previous config</strong> — when you inherit, your rules, whitelists and app lists carry over as-is, and <code>config.json</code> is <strong>merged</strong> with the new defaults: values you changed are kept and newly added options are filled in. Only a corrupt config that cannot be merged falls back to the defaults.</li></ol><p>Once finished, the installer opens the <a href="https://czeropage.top/download-home" target="_blank" rel="noreferrer">download page</a> so the companion app is one tap away.</p><h2 id="after-boot" tabindex="-1">After boot <a class="header-anchor" href="#after-boot" aria-label="Permalink to &quot;After boot&quot;">​</a></h2><p>Once the system is up, the module fixes permissions, initializes its state, and starts the scheduler. You can check its status on the CZeroX home page and restart it in one tap if it didn&#39;t come up.</p><p>If the <a href="/en/guide/features#fine-grained-suppression">fine-grained suppression</a> switches are enabled, boot also configures the system&#39;s suppression capability once; otherwise that step is skipped entirely.</p><h2 id="how-tasks-are-triggered" tabindex="-1">How tasks are triggered <a class="header-anchor" href="#how-tasks-are-triggered" aria-label="Permalink to &quot;How tasks are triggered&quot;">​</a></h2><ul><li><strong>Local-time scheduling</strong> — every task fires against the device&#39;s current time zone; you never touch cron expressions.</li><li><strong>No overlap</strong> — a round is skipped automatically if the previous one hasn&#39;t finished.</li><li><strong>Missed ticks are caught up once</strong> — tasks missed during deep sleep run once on wake; the same task is never caught up more than once, so nothing piles up into consecutive rounds.</li><li><strong>Changes apply immediately</strong> — the scheduler notices <code>config.json</code> changing and reloads on its own, no reboot needed.</li><li><strong>A bad config doesn&#39;t take it down</strong> — if the whole config fails to parse, the last valid job table is retained; if only one schedule is malformed, only that job is skipped and the rest continue.</li></ul><h2 id="what-one-cleaning-run-looks-like" tabindex="-1">What one cleaning run looks like <a class="header-anchor" href="#what-one-cleaning-run-looks-like" aria-label="Permalink to &quot;What one cleaning run looks like&quot;">​</a></h2><p>Using WeChat cache cleaning as an example:</p><ol><li>The task fires and the app&#39;s current state is checked;</li><li>If it is in the foreground, or the foreground is a game, the round is skipped;</li><li>Otherwise cleaning runs, constrained by enhanced mode and the temporal barrier;</li><li>Stats are updated, a log line is written if enabled, and progress and results are reported to CZeroX.</li></ol><h2 id="why-this-design" tabindex="-1">Why this design <a class="header-anchor" href="#why-this-design" aria-label="Permalink to &quot;Why this design&quot;">​</a></h2><ul><li><strong>No resident service</strong> — woken only when needed; otherwise no memory or CPU footprint.</li><li><strong>Single source of truth + hot-reload</strong> — config maps one-to-one to behavior, applies instantly, and a bad config never takes the service down.</li><li><strong>Decoupled native frontend</strong> — CZeroX only reads and writes the config files, so the module runs standalone even without the app.</li></ul>`,20)])])}const u=t(n,[["render",i]]);export{g as __pageData,u as default};
